    return MarkerSchema.parse(parseJsonText(raw, markerPath(projectPath)));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw new Error(`Invalid project marker in ${projectPath}: ${(error as Error).message}`);
  }
}

