export interface WorktreeDependencyBridgeResult {
  status: "not-needed" | "existing-worktree-dependencies" | "created";
  sourcePath?: string;
  bridgePath?: string;
}

export class WorktreeDependencyBridgeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "WorktreeDependencyBridgeError";
  }
}

export async function prepareWorktreeValidationDependencyBridge(projectPath: string, worktree: RunWorktreeInfo | undefined): Promise<WorktreeDependencyBridgeResult> {
  if (!worktree) return { status: "not-needed" };

  const sourcePath = join(projectPath, "node_modules");
  const bridgePath = join(worktree.checkoutPath, "node_modules");

  if (existsSync(bridgePath)) {
    return { status: "existing-worktree-dependencies", sourcePath, bridgePath };
  }

  if (!existsSync(sourcePath)) {
    throw new WorktreeDependencyBridgeError([
      `Cannot run worktree validation for ${worktree.worktreeId}: source project dependencies are missing at ${sourcePath}.`,
      "AHO will not run npm install, npm ci, or any package-manager install command during validation.",
      "Prepare dependencies in the source project, then rerun validation.",
    ].join(" "));
  }

  const sourceInfo = await lstat(sourcePath);
  if (!sourceInfo.isDirectory() && !sourceInfo.isSymbolicLink()) {
    throw new WorktreeDependencyBridgeError(`Cannot run worktree validation for ${worktree.worktreeId}: source dependency path is not a directory: ${sourcePath}.`);
  }

  await symlink(sourcePath, bridgePath, platform() === "win32" ? "junction" : "dir");
  return { status: "created", sourcePath, bridgePath };
}

