  if (!profile) return null;
  if (profile.length === 0) {
    throw new Error(`Validation profile '${profileName}' is empty in harness/config/environment.json.`);
  }
  return {
    name: profileName,
    source: "config",
    commands: profile.map((item) => ({ ...item, source: "config" as const })),
  };
}

